import json, random, subprocess, sys, itertools
sys.path.insert(0,'/workspace/tmp/t')
import ref

def gen(rng):
    LBL = ['a','b','c','test','other','x','end','mid','*','deep','block','n1','n-2','n_3']
    def name(maxd=4, allow_star=True):
        k = rng.randint(0, maxd)
        labs = []
        for _ in range(k):
            if allow_star and rng.random() < 0.12:
                labs.append('*')
            else:
                labs.append(rng.choice(LBL))
        return ('.'+'.'.join(labs)+'.') if labs else '.'
    def wname():
        labs = [rng.choice(LBL) for _ in range(rng.randint(1,3))]
        return '.'+'.'.join(labs)+'.'
    zones = []
    nzone = rng.randint(0,3)
    origins = set()
    for _ in range(nzone):
        o = name(maxd=2, allow_star=False)
        if o == '.':
            continue
        if o in origins: continue
        origins.add(o)
        recs = []
        n = rng.randint(0, 6)
        for _ in range(n):
            owner = o if rng.random() < 0.2 else '.'+'.'.join([rng.choice(LBL) for _ in range(rng.randint(1,3))]+[o[:-1]])+'.'
            t = rng.choice(['A','AAAA','TXT','CNAME'])
            if t == 'A': d = '%d.%d.%d.%d' % (rng.randint(0,255),rng.randint(0,255),rng.randint(0,255),rng.randint(0,255))
            elif t == 'AAAA': d = rng.choice(['2001:db8::1','::1','fe80::a','::ffff:1.2.3.4'])
            elif t == 'TXT': d = rng.choice(['','hi','abc XYZ','x'*10])
            else: d = wname()
            recs.append({'owner':owner,'type':t,'data':d})
        zones.append({'origin':o,'records':recs})
    profiles = []
    for i in range(rng.randint(1,4)):
        profiles.append({'id':'p%d'%i,'max_aliases':rng.choice([0,1,2,3,8]),'cname':rng.choice(['follow','stop']),
                         'wildcard':rng.choice(['rfc','off','one-label'])})
    queries = []
    for i in range(rng.randint(0,6)):
        queries.append({'id':'q%d'%i,'name':name(maxd=4),'type':rng.choice(['A','AAAA','TXT','CNAME']),'cost':rng.randint(1,5)})
    obs = []
    for i in range(rng.randint(0,4)):
        if not queries or not profiles: break
        r = rng.random()
        if r < 0.3:
            res = {'status':'timeout'}
        else:
            ans = []
            for _ in range(rng.randint(0,3)):
                t = rng.choice(['A','AAAA','TXT','CNAME'])
                if t=='A': d='%d.%d.%d.%d'%(rng.randint(0,255),0,0,rng.randint(0,255))
                elif t=='AAAA': d='2001:db8::%x'%rng.randint(0,65535)
                elif t=='TXT': d=rng.choice(['','zz'])
                else: d=wname()
                ans.append({'owner':name(maxd=3),'type':t,'data':d})
            res = {'status':'response','rcode':rng.choice(['NOERROR','NXDOMAIN','SERVFAIL','REFUSED']),'answer':ans}
        obs.append({'id':'o%d'%i,'query':rng.choice(queries)['id'],'profile':rng.choice(profiles)['id'],'result':res})
    return {'zones':zones,'profiles':profiles,'queries':queries,'observations':obs}

def canon_doc(doc):
    # canonicalize exactly like the spec for reference computation
    import ipaddress
    def cn(n): return n.lower()
    zs = []
    for z in doc['zones']:
        recs = []
        for r in z['records']:
            d = r['data']
            if r['type']=='AAAA': d = ipaddress.IPv6Address(d).compressed
            if r['type']=='CNAME': d = d.lower()
            recs.append((r['owner'].lower(), r['type'], d))
        zs.append((z['origin'].lower(), recs))
    return zs

def check(doc, verbose=False):
    zs = ref.build(canon_doc(doc))
    proj = {}
    for q in doc['queries']:
        for p in doc['profiles']:
            rc, term, fin, ans, tr = ref.resolve(zs, q['name'].lower(), q['type'], p)
            proj[(q['id'],p['id'])] = (rc, frozenset(ans))
    eq, basis, cost, count = ref.basis_bruteforce(doc['profiles'], doc['queries'], proj)
    p = subprocess.run([sys.executable,'-I','/workspace/submission/main.py'],
                       input=json.dumps(doc).encode(), capture_output=True, timeout=60)
    assert p.returncode==0, p.stderr[:500]
    out = json.loads(p.stdout.decode())
    if 'error' in out:
        return ('rejected', out)
    # compare runs
    exp_runs = []
    for q in sorted(doc['queries'], key=lambda x:x['id']):
        for pr in sorted(doc['profiles'], key=lambda x:x['id']):
            rc, term, fin, ans, tr = ref.resolve(zs, q['name'].lower(), q['type'], [x for x in doc['profiles'] if x['id']==pr['id']][0])
            exp_runs.append({'query':q['id'],'profile':pr['id'],'rcode':rc,'termination':term,'final_name':fin,
                             'answer':[{'owner':o,'type':t,'data':d} for o,t,d in ans],'trace':tr})
    if out['runs'] != exp_runs:
        return ('runs-mismatch', out['runs'], exp_runs)
    exp_audits = []
    for o in sorted(doc['observations'], key=lambda x:x['id']):
        if o['result']['status']=='timeout':
            exp_audits.append({'id':o['id'],'verdict':'unobserved','different':[]})
        else:
            r = proj[(o['query'],o['profile'])]
            orcr = o['result']['rcode']
            oset = frozenset((x['owner'].lower(), x['type'],
                              ipaddress.IPv6Address(x['data']).compressed if x['type']=='AAAA' else (x['data'].lower() if x['type']=='CNAME' else x['data']))
                             for x in o['result']['answer'])
            d = []
            if r[0]!=orcr: d.append('rcode')
            if r[1]!=oset: d.append('answer')
            exp_audits.append({'id':o['id'],'verdict':'match' if not d else 'divergence','different':d})
    if out['audits'] != exp_audits:
        return ('audits-mismatch', out['audits'], exp_audits)
    dg = out['diagnostic']
    if dg['equivalence']!=eq or dg['cost']!=cost or dg['count']!=count:
        return ('diag-mismatch', dg, (eq,basis,cost,count))
    if dg['basis']!=basis:
        # verify optimality equivalently: same cost/count and valid cover
        if (sum(x['cost'] for x in doc['queries'] if x['id'] in dg['basis']), len(dg['basis'])) != (cost,count):
            return ('basis-suboptimal', dg, (eq,basis,cost,count))
        matrix = proj
        pids = sorted(x['id'] for x in doc['profiles'])
        for a,b in itertools.combinations(pids,2):
            if any(matrix[(q,a)]!=matrix[(q,b)] for q in [x['id'] for x in doc['queries']]):
                if not any(matrix[(q,a)]!=matrix[(q,b)] for q in dg['basis']):
                    return ('basis-invalid', dg, (eq,basis,cost,count))
    return ('ok',)

fails = {}
N = int(sys.argv[1]) if len(sys.argv)>1 else 300
for i in range(N):
    rng = random.Random(i)
    doc = gen(rng)
    try:
        res = check(doc)
    except Exception as e:
        res = ('exception', repr(e))
    if res[0] != 'ok':
        # distinguish genuine rejection (invalid input produced by generator) from mismatch
        if res[0]=='rejected':
            fails.setdefault('rejected',[]).append(i)
        else:
            fails.setdefault(res[0],[]).append(i)
            print('FAIL', i, res[0])
            print(json.dumps(doc))
            if len(fails)>3: break
print('done', {k:(len(v),v[:5]) for k,v in fails.items()})
